/// <summary>
/// Extension of table WrkCtrActivityResourceGroupRequirement
/// </summary>
[ExtensionOf(tableStr(WrkCtrActivityResourceGroupRequirement))]
final public class AVAWrkCtrActivityResourceGroupRequirementDbt_Extension
{
}

Method.Source:
/// <summary>
/// Displays the associated WrkCtrId
/// </summary>
/// <returns>WrkCtrId</returns>
public display WrkCtrId avaDisplayWrkCtrId()
{
    return WrkCtrResourceGroup::find(this.ResourceGroup).WrkCtrId;
}

/// <summary>
/// Gets and sets the resource group based on name.
/// </summary>
/// <param name="_set">
/// true if the resource group name is set; otherwise, false.
/// </param>
/// <param name="_wrkCtrActivityRequirementEdit">
/// The new resource group name value when <paramref name="set"/> is true.
/// </param>
/// <param name="_wrkCtrActivityRequirement">
/// The parent activity requirement record.
/// </param>
/// <param name="_allowBlank">
/// A <c>Boolean</c> specifying if the method accepts a blank string as input.
/// </param>
/// <param name="_companyId">The company ID.</param>
/// <returns>
/// A string with the name of the resource group.
/// </returns>
/// <exception cref="Exception::Warning">
/// The value in field requirement is not found in relating table Resource groups.
/// </exception>
public WrkCtrActivityRequirementEdit requirementEdit(
    boolean                                 _set,
    WrkCtrActivityRequirementEdit           _wrkCtrActivityRequirementEdit,
    WrkCtrActivityRequirement               _wrkCtrActivityRequirement,
    boolean                                 _allowBlank,
    CompanyId                               _companyId
    )
{
    WrkCtrActivityRequirementEdit   avaWrkCtrActivityRequirementEdit = next requirementEdit(_set, _wrkCtrActivityRequirementEdit, _wrkCtrActivityRequirement, _allowBlank, _companyId);
    WrkCtrResourceGroup             avaWrkCtrResourceGroup;

    if (_set
        && _companyId)
    {
        changecompany(_companyId)
        {
            avaWrkCtrResourceGroup = WrkCtrResourceGroup::findWrkCtrId(_wrkCtrActivityRequirementEdit);
            if (avaWrkCtrResourceGroup && (avaWrkCtrResourceGroup.KCS_NotActiveWrkCtr == NoYes::Yes))
            {
                throw warning(strFmt("@NDX:NXAResourceInactiveError", avaWrkCtrResourceGroup.WrkCtrId));
            }
        }
    }

    return avaWrkCtrActivityRequirementEdit;
}
